import {copyFile, mkdir, readFile} from 'node:fs/promises';
import {join} from 'node:path';
import {requireSource} from './renderer-source-data.mjs';

// Use each project's production tsconfig and an empty incremental cache. The SDK
// consumes the WASM declarations generated by the ordinary workspace build.
export async function rebuildRenderer({root,runRoot,child}) {
  const readJson = async path => JSON.parse(await readFile(join(root,path),'utf8'));
  const [workspace,lock,installed] = await Promise.all([
    readJson('package.json'),readJson('package-lock.json'),readJson('node_modules/typescript/package.json'),
  ]);
  const compiler = lock.packages['node_modules/typescript'].version;
  requireSource(compiler === workspace.devDependencies.typescript && compiler === installed.version,'TypeScript version');
  const cache = join(runRoot,'renderer-tsbuildinfo');
  await mkdir(cache);
  const run = async args => {
    const result = await child(process.execPath,args,{cwd:root,stdio:'inherit'},120000);
    requireSource(result.code === 0 && !result.timedOut,'renderer build '+args[0]);
  };
  for (const name of ['sdk','dom','kwdj','ui']) {
    await run(['node_modules/typescript/bin/tsc','-p','packages/'+name,'--tsBuildInfoFile',join(cache,name+'.tsbuildinfo')]);
  }
  await run(['scripts/build-clipboard-parser.mjs']);
  for (const name of ['dom','ui']) {
    const pkg = join(root,'packages',name);
    await copyFile(join(pkg,'src/style.css'),join(pkg,'dist/style.css'));
  }
}
